import React, { useState } from "react"
import { Avatar } from "@sb-components/atoms/display/Avatar/Avatar"
import { Button } from "@sb-components/atoms/buttons/Button/Button"
import { InputTextarea } from "@sb-components/atoms/forms"
import { InputButtonLike } from "@sb-components/composites/buttons/InputButtonLike/InputButtonLike"
import type { AllowedClassName } from "@sb-components/atoms/_allowed-class-name"
import { StackH, StackV } from "@sb-components/frames/Stack/Stack"

/**
 * BLOCK — `ContentCommentComposer`: the textarea + submit control for new
 * comments, replies, and edits — ONE component, three call shapes, ported
 * verbatim from real `src`'s `CommentComposer`. See the component's own file
 * header for why `variant="primary"` (real `Discussion` is frameless — no
 * card ever wraps this field) and why the avatar-led row is top-level only.
 *
 *  LEAVES by STRUCTURE (§14d.2). Collapsed-pill vs expanded-field is a real
 * node swap ⇒ separate leaves. Avatar present/absent is also a node swap
 * (top-level vs reply/edit) ⇒ its own leaf.
 */

/** Minimal identity for the avatar-led top-level composer. */
export interface ContentCommentComposerViewer {
    username: string
    avatarUrl?: string
}

/** Props for {@link ContentCommentComposer}. */
export interface ContentCommentComposerProps {
    /** Called with the trimmed body when the reader submits a non-empty comment. */
    onSubmit: (body: string) => void
    /** Placeholder text for the field. */
    placeholder?: string
    /** Submit button label. */
    submitLabel?: string
    /** Optional cancel handler — renders a cancel button when provided (reply/edit). */
    onCancel?: () => void
    /** Initial field value (editing an existing comment). */
    initialValue?: string
    /** `true` → submit is disabled and shows its busy affordance. */
    isPending?: boolean
    /**
     * Set → the composer is avatar-led (top-level only; reply/edit omit this).
     * `null` → signed-out top-level composer, no avatar.
     */
    currentUser?: ContentCommentComposerViewer | null
    /**
     * `true` → starts collapsed as a slim avatar + placeholder pill, expands to
     * the full field on click (the top-level composer pattern). Reply/edit
     * composers omit this and render expanded.
     */
    collapsible?: boolean
    /** Accessible name for the field. */
    ariaLabel: string
    /** Where this sits inside its parent (placement only, e.g. `flex-1` beside a `ThreadConnector`). */
    classNames?: Array<AllowedClassName>
}

/**
 * The comment/reply/edit composer. See the file header for the full contract.
 *
 * @param props - {@link ContentCommentComposerProps}
 */
const ContentCommentComposer = ({
    onSubmit,
    placeholder = "Ask a question or share your thoughts…",
    submitLabel = "Post",
    onCancel,
    initialValue,
    isPending = false,
    currentUser,
    collapsible = false,
    ariaLabel,
    classNames,
}: ContentCommentComposerProps) => {
    const [body, setBody] = useState(initialValue ?? "")
    // collapsible composers start closed; reply/edit always render expanded
    const [expanded, setExpanded] = useState(!collapsible)
    const trimmed = body.trim()

    const handleSubmit = () => {
        if (!trimmed) {
            return
        }
        onSubmit(trimmed)
        setBody("")
        if (collapsible) {
            setExpanded(false)
        }
    }

    const handleCancel = () => {
        setBody("")
        if (collapsible) {
            setExpanded(false)
        }
        onCancel?.()
    }

    // collapsed pill: avatar + placeholder, the whole row opens the composer
    if (collapsible && !expanded) {
        return (
            <StackH
                gap={4}
                principles={["content-row"]}
                align="center"

                items={[
                    ...(currentUser ? [() => (
                        <Avatar src={currentUser.avatarUrl} name={currentUser.username} seed={currentUser.username} size="sm" />
                    )] : []),
                    () => (
                        <div className="min-w-0 flex-1">
                            <InputButtonLike
                                placeholder={placeholder}
                                ariaLabel={ariaLabel}
                                onPress={() => setExpanded(true)}
                            />
                        </div>
                    ),
                ]}
            />
        )
    }

    const buttonRow = (
        <>
            <Button
                label={submitLabel}
                size="sm"
                onPress={handleSubmit}
                isDisabled={!trimmed}
                isPending={isPending}

            />
            {onCancel || collapsible ? (
                <Button
                    label="Cancel"
                    variant="tertiary"
                    size="sm"
                    onPress={handleCancel}
                    isDisabled={isPending}

                />
            ) : null}
        </>
    )

    const fieldColumn = (
        <>
            <InputTextarea
                value={body}
                onValueChange={setBody}
                placeholder={placeholder}
                ariaLabel={ariaLabel}
                rows={3}
                variant="primary"

            />
            <StackH gap={3} items={[() => buttonRow]} />
        </>
    )

    const composerRow = (
        <>
            {currentUser ? (
                <Avatar src={currentUser.avatarUrl} name={currentUser.username} seed={currentUser.username} size="sm" />
            ) : null}
            <StackV gap={3} classNames={["min-w-0", "flex-1"]} items={[() => fieldColumn]} />
        </>
    )

    return (
        <StackH gap={4} principles={["content-row"]} align="start" classNames={classNames} items={[() => composerRow]} />
    )
}

export { ContentCommentComposer }

import React, { useState } from "react"
import { type SkeletonProps } from "@sb-components/frames/_slot"
import { Avatar } from "@sb-components/atoms/display/Avatar/Avatar"
import { Button } from "@sb-components/atoms/buttons/Button/Button"
import { InputTextarea } from "@sb-components/atoms/forms"
import { InputButtonLike } from "@sb-components/composites/buttons/InputButtonLike/InputButtonLike"
import { StackH, StackV } from "@sb-components/frames/Stack/Stack"

/**
 * BLOCK — `CourseQaComposer`: the ONE writing shape reused three ways on a
 * course Q&A board — the root "ask the whole course" collapsible pill, an
 * answer's inline edit form, and an inline reply form. See the component file
 * header for the full mode/`initialValue`/fold-back contract and why this is
 * genuinely new rather than a duplicate of `_legacy/blocks/feed/Composer`.
 */

/** Which of the block's two writing shapes to render. */
export type CourseQaComposerMode = "collapsible" | "plain"

/** The signed-in viewer writing this — plain data, the block builds the avatar from it. */
export interface CourseQaComposerUser {
    /** Display name; also seeds the avatar's initials fallback. */
    name: string
    /** Avatar image URL. Omitted → the avatar falls back per its own chain. */
    avatarSrc?: string
}

/** Props for {@link CourseQaComposer}. */
export interface CourseQaComposerProps {
    /**
     * `"collapsible"` — boots as a slim avatar + placeholder pill, opens into the
     * full form on press (the root "ask the whole course" composer). `"plain"` —
     * always the full form (an answer's inline edit, an inline reply, or a
     * bottom "write an answer" box).
     */
    mode: CourseQaComposerMode
    /** The signed-in viewer. Omitted → no leading avatar is drawn (either shape). */
    currentUser?: CourseQaComposerUser
    /**
     * Existing content this composer opened WITH (an edit/reply reopened, not a
     * fresh draft). Read once, only to decide a `"collapsible"` composer's BOOT
     * state — see the file header. Never re-consulted after mount; the live
     * draft is entirely `value`/`onValueChange`.
     */
    initialValue?: string
    /** The current draft text — fully controlled by the caller. */
    value: string
    /** Fired with the next draft text on every keystroke. */
    onValueChange: (value: string) => void
    /** Placeholder for both the collapsed pill and the open textarea. */
    placeholder?: string
    /** Label for the submit button. Defaults to `"Send"`. */
    submitLabel?: string
    /**
     * Fired when the viewer submits. The caller already holds the draft via
     * `value`, so this fires with no argument. A `"collapsible"` composer folds
     * itself back to the pill right after — the caller is still responsible for
     * clearing `value`.
     */
    onSubmit: () => void
    /**
     * Fired when the viewer backs out. Shown whenever `mode === "collapsible"`
     * (folding back to the pill always needs a way out) or whenever the caller
     * supplies this (the edit/reply shapes of `mode === "plain"`).
     */
    onCancel?: () => void
    /** `true` → submit is in flight: the Submit button owns the busy affordance and both buttons lock. */
    isPending?: boolean
    /**
     * `true` → every composed atom mirrors itself. The flag FLOWS DOWN into the
     * real atoms (§12c) rather than a parallel skeleton tree, within whichever
     * leaf (`CollapsedPrompt`/`ExpandedForm`) is currently showing.
     */
    isSkeleton?: boolean
}

/**
 * The Q&A board's one writing shape. See the file header for the mode
 * contract, the controlled-text/`initialValue` split, and the fold-back
 * judgement call.
 *
 * @param props - {@link CourseQaComposerProps}
 */
const CourseQaComposer = ({
    mode,
    currentUser,
    initialValue,
    value,
    onValueChange,
    placeholder,
    submitLabel = "Send",
    onSubmit,
    onCancel,
    isPending = false,
    isSkeleton = false,
}: CourseQaComposerProps) => {
    // Transient UI-only chrome (§ not domain data) — owned here, never lifted to
    // the caller. A "plain" composer has no collapsed shape at all, so it always
    // boots open; a "collapsible" one boots open only when reopened WITH content.
    const [expanded, setExpanded] = useState(() => mode === "plain" || Boolean(initialValue))

    const canSubmit = value.trim().length > 0 && !isPending
    const showCancel = mode === "collapsible" || onCancel != null

    const handleSubmit = () => {
        onSubmit()
        // Folding back is presentational chrome the block owns; the caller still
        // clears `value` itself (it owns the draft) — see file header.
        if (mode === "collapsible") {
            setExpanded(false)
        }
    }

    const handleCancel = () => {
        if (mode === "collapsible") {
            setExpanded(false)
        }
        onCancel?.()
    }

    const avatar = currentUser || isSkeleton ? (
        <Avatar
            name={currentUser?.name}
            src={currentUser?.avatarSrc}
            size="sm"
            isSkeleton={isSkeleton}


        />
    ) : null

    // ── LEAF — CollapsedPrompt: avatar + pill, nothing else composed ──────────
    if (mode === "collapsible" && !expanded) {
        return (
            <div>
                <StackH
                    gap={3}
                    isSkeleton={isSkeleton}
                    items={[
                        () => avatar,
                        () => (
                            <div className="min-w-0 flex-1">
                                <InputButtonLike
                                    placeholder={placeholder ?? "Ask a question about this course…"}
                                    onPress={() => setExpanded(true)}
                                    isSkeleton={isSkeleton}
                                />
                            </div>
                        ),
                    ]}
                />
            </div>
        )
    }

    // ── LEAF — ExpandedForm: avatar + textarea + action row ───────────────────
    const actionRow = (
        <>
            {showCancel ? (
                <Button
                    label="Cancel"
                    variant="tertiary"
                    size="sm"
                    onPress={handleCancel}
                    isDisabled={isPending}
                    isSkeleton={isSkeleton}

                />
            ) : null}
            <Button
                label={submitLabel}
                variant="primary"
                size="sm"
                onPress={handleSubmit}
                isDisabled={!canSubmit}
                isPending={isPending}
                isSkeleton={isSkeleton}

            />
        </>
    )

    const form = (
        <>
            <InputTextarea
                value={value}
                onValueChange={onValueChange}
                placeholder={placeholder}
                ariaLabel={placeholder ?? "Content"}
                rows={3}
                isDisabled={isPending}
                isSkeleton={isSkeleton}

            />
            <StackH gap={3} principles={["flex-action"]} justify="end" isSkeleton={isSkeleton} items={[() => actionRow]} />
        </>
    )

    return (
        <div>
            <StackH
                gap={3}
                isSkeleton={isSkeleton}
                items={[
                    () => avatar,
                    ({ isSkeleton }: SkeletonProps) => <StackV gap={3} isSkeleton={isSkeleton} classNames={["min-w-0", "flex-1"]} items={[() => form]} />,
                ]}
            />
        </div>
    )
}

export { CourseQaComposer }

import React from "react"
import { type SkeletonProps } from "@sb-components/frames/_slot"
import { Skeleton as HeroSkeleton } from "@heroui/react"
import { ArrowRightIcon, CheckCircleIcon, WarningCircleIcon, XCircleIcon } from "@phosphor-icons/react"
import { Chip } from "@sb-components/atoms/chips/Chip/Chip"
import { Typography } from "@sb-components/atoms/text/Typography/Typography"
import { Button } from "@sb-components/atoms/buttons/Button/Button"
import { SurfaceCard, SurfaceCardCrossList, type SurfaceCardCrossListItem } from "@sb-components/composites/cards/SurfaceCard/SurfaceCard"
import { Callout, type CalloutIcon } from "@sb-components/composites/feedback/Callout/Callout"
import { MarkdownContent } from "@sb-components/composites/viewers/MarkdownContent/MarkdownContent"
import { StackH, StackV } from "@sb-components/frames/Stack/Stack"
import { ScoreRow } from "./ScoreRow"
import { ScoreRowSkeleton } from "./ScoreRowSkeleton"

/**
 * `MockInterviewScorecard` — read-only render of one graded mock-interview run:
 * a verdict banner (`Callout`), hand-laid `ProgressMeter` rows for the score and
 * attribute breakdowns, and strengths/gaps via `SurfaceCard.CrossList`. Every
 * optional section — byline, attribute breakdown, strengths, gaps, follow-up,
 * weak-area tag, retry — is a state of one shape. Per-question model-answer review
 * is out of scope (no primitive for it yet).
 */

/** Pass / borderline / fail — reuses the interview verdict vocabulary verbatim from the BE contract. */
export type MockInterviewVerdict = "pass" | "borderline" | "fail"

/** One row of the score breakdown — a phase (design mode) or a question ordinal (Q&A mode), already display-labeled by the caller. */
export interface MockInterviewScoreRow {
    /** Stable React key. */
    key: string
    /** Display label — a resolved phase name or a question ordinal ("Question 1"), already localized/resolved by the caller. */
    label: string
    /** Points earned for this phase/question. */
    score: number
    /** Points available for this phase/question. */
    max: number
}

/** One row of the attribute breakdown (communication, structured thinking …), 0–100. */
export interface MockInterviewAttributeScoreRow {
    /** Stable React key. */
    key: string
    /** Display label, already localized/resolved by the caller. */
    label: string
    /** 0–100. */
    score: number
}

/** Props for {@link MockInterviewScorecard}. */
export interface MockInterviewScorecardProps {
    /** Pass / borderline / fail — drives the verdict callout's tone, icon and wording. */
    verdict: MockInterviewVerdict
    /** Overall score, 0–100. */
    overallScore: number
    /** Per-phase or per-question score breakdown, in display order. Section self-hides when empty (and `isSkeleton` is off). */
    phaseOrQuestionScores: Array<MockInterviewScoreRow>
    /** Per-attribute score breakdown, in display order. Section self-hides when empty. */
    attributeScores: Array<MockInterviewAttributeScoreRow>
    /** Concrete things done right, as markdown. Section self-hides when empty. */
    strengths: Array<string>
    /** Concrete gaps framed as "what to add", as markdown. Section self-hides when empty. */
    gaps: Array<string>
    /** A follow-up an interviewer would ask next, as markdown. Omit → the section does not render. */
    followUpQuestion?: string | null
    /** The weakest area, already resolved by the caller (which phase/attribute counts as "weak enough to push" is a screen-level call, not this block's). Omit → the primary CTA reads generically. */
    weakAreaLabel?: string
    /** Fired when the learner takes the primary CTA — go study the weak area. */
    onStudyWeakArea: () => void
    /** Fired when the learner picks the capstone hand-off CTA. */
    onCapstone: () => void
    /** Fired when the learner wants to run the interview again. Omit → the retry action does not render (e.g. a read-only history detail). */
    onRetry?: () => void
    /** The system/prompt this run interviewed on, shown as a header line when known. */
    promptTitle?: string
    /** When this attempt was graded, already formatted/localized by the caller (e.g. "Jul 28, 2026 · 14:32"). Omit for a live, just-finished session. */
    createdAt?: string
    /** `true` → every part this block renders itself mirrors as shimmer. */
    isSkeleton?: boolean
}

/** Verdict → callout tone. */
const VERDICT_STATUS: Record<MockInterviewVerdict, "success" | "warning" | "danger"> = {
    pass: "success",
    borderline: "warning",
    fail: "danger",
}

/** Verdict → callout indicator icon. */
const VERDICT_ICON: Record<MockInterviewVerdict, CalloutIcon> = {
    pass: CheckCircleIcon,
    borderline: WarningCircleIcon,
    fail: XCircleIcon,
}

/** Verdict → the block's own wording (§14d.1 — a caller passes the enum, never a formatted string). */
const VERDICT_LABEL: Record<MockInterviewVerdict, string> = {
    pass: "Pass",
    borderline: "Borderline",
    fail: "Fail",
}

/** Placeholder row count while `isSkeleton` and the real breakdown length isn't known yet. */
const SKELETON_SCORE_ROWS = 3
const SKELETON_ATTRIBUTE_ROWS = 3

/**
 * The graded-run scorecard. See the file header for the full contract, the
 * scope cut (no per-question review this pass), and why every optional
 * section stays a STATE of this one leaf.
 *
 * @param props - {@link MockInterviewScorecardProps}
 */
const MockInterviewScorecard = ({
    verdict,
    overallScore,
    phaseOrQuestionScores,
    attributeScores,
    strengths,
    gaps,
    followUpQuestion,
    weakAreaLabel,
    onStudyWeakArea,
    onCapstone,
    onRetry,
    promptTitle,
    createdAt,
    isSkeleton = false,
}: MockInterviewScorecardProps) => {
    const hasByline = isSkeleton || promptTitle != null || createdAt != null
    const hasScoreRows = isSkeleton || phaseOrQuestionScores.length > 0
    const hasAttributeRows = isSkeleton || attributeScores.length > 0
    const hasStrengths = isSkeleton || strengths.length > 0
    const hasGaps = isSkeleton || gaps.length > 0
    const hasFollowUp = isSkeleton || Boolean(followUpQuestion)

    const strengthItems: Array<SurfaceCardCrossListItem> = strengths.map((strength, index) => ({
        key: `strength-${index}`,
        mark: "check",
        tone: "success",
        text: strength,
    }))

    const gapItems: Array<SurfaceCardCrossListItem> = gaps.map((gap, index) => ({
        key: `gap-${index}`,
        mark: "cross",
        tone: "danger",
        text: gap,
    }))

    const primaryCtaLabel = weakAreaLabel ? `Review: ${weakAreaLabel}` : "Review your weak areas"

    const bylineRow = hasByline ? (
        <StackH
            gap={4}
            justify="between"
            at="sm"
            principles={["content-row"]}
            isSkeleton={isSkeleton}
            items={[
                () => (isSkeleton ? (
                    <Typography size="sm" weight="medium" isSkeleton />
                ) : promptTitle != null ? (
                    <Typography size="sm" weight="medium" text={promptTitle} />
                ) : null),
                () => (isSkeleton ? (
                    <Typography size="xs" color="muted" isSkeleton />
                ) : createdAt != null ? (
                    <Typography size="xs" color="muted" text={createdAt} />
                ) : null),
            ]}
        />
    ) : null

    const scoreBreakdownBody = (
        <>
            {isSkeleton
                ? Array.from({ length: SKELETON_SCORE_ROWS }, (_, index) => (
                    <ScoreRowSkeleton key={`score-skeleton-${index}`} />
                ))
                : phaseOrQuestionScores.map((row) => (
                    <ScoreRow key={row.key} label={row.label} score={row.score} max={row.max} />
                ))}
        </>
    )

    const attributeBreakdownBody = (
        <>
            {isSkeleton
                ? Array.from({ length: SKELETON_ATTRIBUTE_ROWS }, (_, index) => (
                    <ScoreRowSkeleton key={`attribute-skeleton-${index}`} />
                ))
                : attributeScores.map((row) => (
                    <ScoreRow key={row.key} label={row.label} score={row.score} max={100} />
                ))}
        </>
    )

    const strengthsBody = (
        <>
            <Typography size="sm" weight="medium" text="Strengths" />
            <SurfaceCardCrossList items={strengthItems} isSkeleton={isSkeleton} />
        </>
    )

    const gapsBody = (
        <>
            <Typography size="sm" weight="medium" text="Areas to improve" />
            <SurfaceCardCrossList items={gapItems} isSkeleton={isSkeleton} />
        </>
    )

    const weakAreaRow = weakAreaLabel != null && !isSkeleton ? (
        <StackH
            gap={2}
            align="center"
            principles={["icon-text"]}
            isSkeleton={isSkeleton}
            items={[
                ({ isSkeleton }: SkeletonProps) => <Typography size="xs" color="muted" text="Weakest:" isSkeleton={isSkeleton} />,
                ({ isSkeleton }: SkeletonProps) => <Chip tone="warning" text={weakAreaLabel} isSkeleton={isSkeleton} />,
            ]}
        />
    ) : null

    const ctaButtonRow = (
        <StackH
            gap={4}
            at="sm"
            principles={["flex-action"]}
            isSkeleton={isSkeleton}
            items={[
                () => (
                    <Button
                        isSkeleton={isSkeleton}
                        variant="primary"
                        size="lg"
                        label={primaryCtaLabel}
                        suffixIcon={ArrowRightIcon}
                        iconSlide
                        onPress={onStudyWeakArea}

                    />
                ),
                () => (
                    <Button
                        isSkeleton={isSkeleton}
                        variant="secondary"
                        size="lg"
                        label="Work on personal project"
                        onPress={onCapstone}

                    />
                ),
                ...(onRetry != null || isSkeleton ? [() => (
                    <Button
                        isSkeleton={isSkeleton}
                        variant="ghost"
                        size="lg"
                        label="Retry interview"
                        onPress={onRetry}

                    />
                )] : []),
            ]}
        />
    )

    const ctaSection = (
        <>
            {weakAreaRow}
            {ctaButtonRow}
        </>
    )

    const scorecardBody = (
        <>
            {bylineRow}

            {/* Verdict banner. `Callout` has no `isSkeleton` of its own (a message
                frame, not a data-bearing one) — a bare bar stands in, in the same slot. */}
            {isSkeleton ? (
                <HeroSkeleton className="h-20 w-full rounded-2xl" />
            ) : (
                <Callout
                    status={VERDICT_STATUS[verdict]}
                    icon={VERDICT_ICON[verdict]}
                    title={`${overallScore}/100 · ${VERDICT_LABEL[verdict]}`}

                />
            )}

            {hasScoreRows ? (
                <SurfaceCard
                    label="Score by section"


                    body={() => <StackV gap={4} isSkeleton={isSkeleton} items={[() => scoreBreakdownBody]} />}
                />
            ) : null}

            {hasAttributeRows ? (
                <SurfaceCard
                    label="Score by criterion"


                    body={() => <StackV gap={4} isSkeleton={isSkeleton} items={[() => attributeBreakdownBody]} />}
                />
            ) : null}

            {hasStrengths ? (
                <StackV gap={3} isSkeleton={isSkeleton} items={[() => strengthsBody]} />
            ) : null}

            {hasGaps ? (
                <StackV gap={3} isSkeleton={isSkeleton} items={[() => gapsBody]} />
            ) : null}

            {/* no icon here — §5a.2: a chat-bubble needs an ASSOCIATION step to read as
                "a question" (not a universal symbol like check/locklock), and the card's own
                label="Follow-up question" already carries the fact. */}
            {hasFollowUp ? (
                <SurfaceCard
                    label="Follow-up question"


                    body={() => (
                        <div className="italic [&_p]:m-0">
                            <MarkdownContent
                                source={followUpQuestion ?? ""}
                                measure="compact"
                                isSkeleton={isSkeleton}

                            />
                        </div>
                    )}
                />
            ) : null}

            <StackV gap={3} isSkeleton={isSkeleton} items={[() => ctaSection]} />
        </>
    )

    return (
        <div>
            <StackV gap={6} isSkeleton={isSkeleton} items={[() => scorecardBody]} />
        </div>
    )
}

export { MockInterviewScorecard }

import React from "react"
import { ProgressMeter } from "@sb-components/composites/stats/ProgressMeter/ProgressMeter"
import { Typography } from "@sb-components/atoms/text/Typography/Typography"
import { StackH } from "@sb-components/frames/Stack/Stack"

/**
 * Score bar/text color BY VALUE, not a fixed tone — a low score must read as
 * low. Ported unchanged from the source `scoreColorOf`.
 */
const scoreColorOf = (score: number, max: number): "success" | "warning" | "danger" => {
    const ratio = max > 0 ? score / max : 0
    return ratio < 0.5 ? "danger" : ratio < 0.75 ? "warning" : "success"
}

/** One labeled score row: a truncating label, a value-colored bar, and the raw "earned/max" beside it. */
interface ScoreRowProps {
    label: string
    score: number
    max: number
}
export const ScoreRow = ({
    label,
    score,
    max,
}: ScoreRowProps) => (
    <StackH
        gap={4}
        align="center"
        principles={["content-row"]}
        items={[
            () => <Typography size="sm" truncate text={label} />,
            () => <ProgressMeter value={score} max={max} color={scoreColorOf(score, max)} classNames={["flex-1"]} />,
            () => <Typography size="xs" color="muted" tabularNums text={`${score}/${max}`} />,
        ]}
    />
)

import React, { useState } from "react"
import { type SkeletonProps } from "@sb-components/frames/_slot"
import type { ReactNode } from "react"
import { Tabs } from "@heroui/react"
import {
    ArrowClockwiseIcon,
    ArrowsClockwiseIcon,
} from "@phosphor-icons/react"
import { SurfaceCard } from "@sb-components/composites/cards/SurfaceCard/SurfaceCard"
import { EnumChip, type EnumChipEntry } from "@sb-components/composites/chips/EnumChip/EnumChip"
import { MarkdownContent } from "@sb-components/composites/viewers/MarkdownContent/MarkdownContent"
import { TabsExtended } from "@sb-components/atoms/navigation/Tabs/Tabs"
import { Button } from "@sb-components/atoms/buttons/Button/Button"
import { Callout } from "@sb-components/composites/feedback/Callout/Callout"
import { ConfirmDialog } from "@sb-components/composites/feedback/ConfirmDialog/ConfirmDialog"
import { Typography } from "@sb-components/atoms/text/Typography/Typography"
import { StackV, StackH } from "@sb-components/frames/Stack/Stack"
import { CommandSkeleton } from "./CommandSkeleton"
import { OsTabsSkeleton } from "./OsTabsSkeleton"
import { type PlaygroundSetupOs, type PlaygroundSetupStepsProps } from "./types"

export type { PlaygroundSetupOs, PlaygroundSetupFlavor, PlaygroundSetupStepsProps } from "./types"

/**
 * BLOCK — `PlaygroundSetupSteps`: the ordered setup guide for a playground — pair
 * the local agent, install the engine (an OS-tabbed guide), and — Ollama flavor
 * only — pull the VRAM-sized models. Each step carries its own status chip,
 * why-it-matters line, runnable command(s), and re-check action.
 *
 * TWO LEAVES, ONE PER `flavor` (§14d.2 — see the component's file header for why
 * this differs from `ChallengeBrief`'s single "one leaf, N optional sections"):
 * `flavor` is chosen once per PLAYGROUND KIND, not per render, so a caller wired
 * to `"infra"` never even carries the model-readiness props the third step
 * needs — the third `SurfaceCard` is a structural fact of the ollama leaf, not a
 * data condition that could show up on the infra one.
 */

/** One `SurfaceCard` step, built by this block before render — named per §"every data shape has a name". */
interface StepEntry {
    key: string
    title: string
    status: StepStatus
    body: ReactNode
}

/** Fixed platform-wide embedding model — see file header: unlike the generation model, this never varies by device. */
const EMBEDDING_MODEL_NAME = "bge-m3"

const OS_ORDER: ReadonlyArray<PlaygroundSetupOs> = ["mac", "win", "linux"]
const OS_LABEL: Record<PlaygroundSetupOs, string> = { mac: "macOS", win: "Windows", linux: "Linux" }

/** The two-value readiness enum driving every step's trailing chip. */
type StepStatus = "ready" | "pending"

/** status → chip label/color — fixed Vietnamese copy this block owns (§14d.1), matching `PlaygroundReadinessChecklist`'s table. */
const STEP_STATUS_MAP: Record<StepStatus, EnumChipEntry> = {
    ready: { label: "Ready", color: "success" },
    pending: { label: "Not done", color: "default" },
}

/** Wraps a shell command in a fenced ```bash block for `MarkdownContent`. */
const bashBlock = (command: string): string => "```bash\n" + command + "\n```"

/**
 * The playground setup guide. See the file header for the reuse check, the
 * two-leaves-per-flavor call, and the skeleton-mirror judgement calls.
 *
 * @param props - {@link PlaygroundSetupStepsProps}
 */
const PlaygroundSetupSteps = ({
    flavor,
    engineName,
    osGuides,
    pairCommand,
    pairingCodeSecondsLeft = null,
    pairingCodeExpired = false,
    onRefreshPairingCode,
    isRefreshingPairingCode = false,
    agentReady,
    engineReady,
    genModelReady = false,
    embedModelReady = false,
    recommendedGenModel,
    deviceKnown = true,
    engineDetail,
    onVerify,
    isSkeleton = false,
}: PlaygroundSetupStepsProps) => {
    const [os, setOs] = useState<PlaygroundSetupOs>("mac")
    const [isRotateConfirmOpen, setRotateConfirmOpen] = useState(false)

    // Rotating a code nobody's agent holds yet is free; rotating a code the connected
    // agent depends on is disruptive, so THAT path confirms first (see file header).
    const handleRotateClick = () => {
        if (!onRefreshPairingCode) return
        if (agentReady) {
            setRotateConfirmOpen(true)
        } else {
            onRefreshPairingCode()
        }
    }
    const handleConfirmRotate = () => {
        onRefreshPairingCode?.()
        setRotateConfirmOpen(false)
    }

    // Shared by every step (see PROPS doc on `onVerify`) — built once as functions, not a
    // single JSX element re-used across positions, so each step gets its own element instance.
    const renderVerifyButton = (): ReactNode => {
        if (isSkeleton) return <Button isSkeleton size="sm" />
        if (!onVerify) return null
        return (
            <Button
                label="Check again"
                variant="tertiary"
                size="sm"
                prefixIcon={ArrowClockwiseIcon}
                onPress={onVerify}

            />
        )
    }
    const renderRotateButton = (): ReactNode => {
        if (isSkeleton) return <Button isSkeleton size="sm" />
        if (!onRefreshPairingCode) return null
        return (
            <Button
                label="Get new code"
                variant="tertiary"
                size="sm"
                prefixIcon={ArrowsClockwiseIcon}
                onPress={handleRotateClick}
                isPending={isRefreshingPairingCode}

            />
        )
    }

    const pairingCodeNote: ReactNode = pairingCodeExpired
        ? (
            <Typography
                size="xs"
                color="danger"
                text="The pairing code has expired — get a new code to continue."

            />
        )
        : pairingCodeSecondsLeft != null
            ? (
                <Typography
                    size="xs"
                    color="muted"
                    text={`Code valid for ${pairingCodeSecondsLeft} more seconds`}

                />
            )
            : null

    const pairStepBody: ReactNode = (
        <StackV
            gap={3}
            principles={["sibling-stack"]}
            isSkeleton={isSkeleton}
            items={[
                () => (
                    <Typography
                        size="sm"
                        color="muted"
                        isSkeleton={isSkeleton}
                        text="The local agent is the bridge that lets Playground control your machine — skip this step and every command in the following steps fails to run."

                    />
                ),
                () => (isSkeleton
                    ? <CommandSkeleton />
                    : <MarkdownContent source={bashBlock(pairCommand)} measure="compact" />),
                ...(!isSkeleton ? [() => pairingCodeNote] : []),
                ({ isSkeleton }: SkeletonProps) => (
                    <StackH
                        gap={3}
                        at="sm"
                        principles={["flex-action"]}
                        isSkeleton={isSkeleton}
                        items={[
                            () => renderVerifyButton(),
                            () => renderRotateButton(),
                        ]}
                    />
                ),
            ]}
        />
    )

    const engineLabel = engineName ?? "engine"
    const osTabsRow: ReactNode = isSkeleton ? (
        <OsTabsSkeleton />
    ) : (
        <div>
            <TabsExtended
                variant="secondary"
                size="sm"
                selectedKey={os}
                onSelectionChange={(key) => setOs(key as PlaygroundSetupOs)}

            >
                <Tabs.ListContainer>
                    <Tabs.List aria-label="Choose operating system">
                        {OS_ORDER.map((key) => (
                            <Tabs.Tab key={key} id={key}>
                                <span>{OS_LABEL[key]}</span>
                                <Tabs.Indicator />
                            </Tabs.Tab>
                        ))}
                    </Tabs.List>
                </Tabs.ListContainer>
                {/* react-aria's useTab always computes an `aria-controls` id — this row shows no
                    panel content of its own (the guide below is a SEPARATE markdown render), so
                    these stay empty/`sr-only`, same convention as `Toolbar`/`Tabs` atom. */}
                {OS_ORDER.map((key) => (
                    <Tabs.Panel key={key} id={key} className="sr-only">{null}</Tabs.Panel>
                ))}
            </TabsExtended>
        </div>
    )

    const engineStepBody: ReactNode = (
        <StackV
            gap={3}
            isSkeleton={isSkeleton}
            items={[
                () => (
                    <Typography
                        size="sm"
                        color="muted"
                        isSkeleton={isSkeleton}
                        text={`${engineLabel} is where the model actually runs on your machine — once installed, Playground can handle local AI tasks.`}

                    />
                ),
                () => osTabsRow,
                () => (isSkeleton
                    ? <CommandSkeleton lines={3} />
                    : <MarkdownContent source={osGuides[os]} measure="compact" />),
                ...(!isSkeleton && engineReady && engineDetail ? [() => (
                    <Callout
                        status="success"
                        title={`${engineLabel} is ready`}
                        description={engineDetail}


                    />
                )] : []),
                ({ isSkeleton }: SkeletonProps) => <StackH gap={3} isSkeleton={isSkeleton} items={[() => renderVerifyButton()]} />,
            ]}
        />
    )

    const genModelCommand = recommendedGenModel != null ? bashBlock(`ollama pull ${recommendedGenModel}`) : null
    const embedModelCommand = bashBlock(`ollama pull ${EMBEDDING_MODEL_NAME}`)
    const modelsReady = genModelReady && embedModelReady

    const genModelSection = genModelCommand != null ? (
        <StackV
            gap={2}
            isSkeleton={isSkeleton}
            items={[
                ({ isSkeleton }: SkeletonProps) => (
                    <Typography
                        isSkeleton={isSkeleton}
                        size="xs"
                        color="muted"
                        text={`Model sinh — ${recommendedGenModel}`}

                    />
                ),
                () => <MarkdownContent source={genModelCommand} measure="compact" />,
            ]}
        />
    ) : null

    const embedModelSection = (
        <StackV
            gap={2}
            isSkeleton={isSkeleton}
            items={[
                ({ isSkeleton }: SkeletonProps) => (
                    <Typography
                        isSkeleton={isSkeleton}
                        size="xs"
                        color="muted"
                        text={`Model embedding — ${EMBEDDING_MODEL_NAME}`}

                    />
                ),
                () => <MarkdownContent source={embedModelCommand} measure="compact" />,
            ]}
        />
    )

    const modelsCommandsSection = (
        <StackV
            gap={4}
            isSkeleton={isSkeleton}
            items={[
                () => genModelSection,
                () => embedModelSection,
            ]}
        />
    )

    const modelsSkeletonCommands = (
        <StackV
            gap={3}
            isSkeleton={isSkeleton}
            items={[
                () => <CommandSkeleton />,
                () => <CommandSkeleton />,
            ]}
        />
    )

    const modelsStepBody: ReactNode = (
        <StackV
            gap={3}
            isSkeleton={isSkeleton}
            items={[
                () => (
                    <Typography
                        size="sm"
                        color="muted"
                        isSkeleton={isSkeleton}
                        text="Models need to be pulled to your machine before use — the right size for your VRAM keeps things running smoothly, without freezing or running out of memory."

                    />
                ),
                () => (isSkeleton ? (
                    modelsSkeletonCommands
                ) : deviceKnown === false ? (
                    <Callout
                        status="warning"
                        title="Device configuration not detected yet"
                        description="Finish installing the engine, then press Check again — Playground will detect your VRAM and suggest the right model size."


                    />
                ) : modelsReady ? (
                    <Callout
                        status="success"
                        title="All models are ready"
                        description="Both the text-generation model and the embedding model are already downloaded on your machine."


                    />
                ) : (
                    modelsCommandsSection
                )),
                ({ isSkeleton }: SkeletonProps) => <StackH gap={3} isSkeleton={isSkeleton} items={[() => renderVerifyButton()]} />,
            ]}
        />
    )

    const agentStatus: StepStatus = agentReady ? "ready" : "pending"
    const engineStatus: StepStatus = engineReady ? "ready" : "pending"
    const modelsStatus: StepStatus = modelsReady ? "ready" : "pending"

    const steps: Array<StepEntry> = [
        { key: "pair", title: "1. Pair local agent", status: agentStatus, body: pairStepBody },
        { key: "engine", title: `2. Install ${engineLabel}`, status: engineStatus, body: engineStepBody },
    ]
    if (flavor === "ollama") {
        steps.push({ key: "models", title: "3. Pull models for your device", status: modelsStatus, body: modelsStepBody })
    }

    // Depends on the loop variable, so it cannot be hoisted to a const above the
    // return — a small named helper instead, in the style this file already uses.
    const renderStep = (step: StepEntry) => (
        <SurfaceCard
            key={step.key}
            label={step.title}
            action={() => (
                <EnumChip
                    value={step.status}
                    map={STEP_STATUS_MAP}
                    isSkeleton={isSkeleton}

                />
            )}
            isSkeleton={isSkeleton}


            body={() => step.body}
        />
    )

    const rotateConfirm = onRefreshPairingCode ? (
        <ConfirmDialog
            isOpen={isRotateConfirmOpen}
            onOpenChange={setRotateConfirmOpen}
            title="Get a new code while the agent is connected?"
            description="The agent is currently using the old code to hold its connection — getting a new code will break the current session until you paste the new code into the agent."
            confirmLabel="Get new code"
            cancelLabel="Not now"
            onConfirm={handleConfirmRotate}
            isConfirming={isRefreshingPairingCode}

        />
    ) : null

    return (
        <StackV
            gap={4}
            isSkeleton={isSkeleton}
            items={[
                ...steps.map((step) => () => renderStep(step)),
                () => rotateConfirm,
            ]}
        />
    )
}

export { PlaygroundSetupSteps }

import React from "react"
import { CheckCircleIcon } from "@phosphor-icons/react"
import { cn } from "@heroui/react"
import { Avatar } from "@sb-components/atoms/display/Avatar/Avatar"
import { Chip } from "@sb-components/atoms/chips/Chip/Chip"
import { Button } from "@sb-components/atoms/buttons/Button/Button"
import { Typography } from "@sb-components/atoms/text/Typography/Typography"
import { MarkdownContent } from "@sb-components/composites/viewers/MarkdownContent/MarkdownContent"
import { StackH, StackV } from "@sb-components/frames/Stack/Stack"
import { QaChatBubble } from "@sb-components/starci/blocks/learn/QaChatBubble/QaChatBubble"
import { QaReactionBar, type QaReactionType } from "@sb-components/starci/blocks/learn/QaReactionBar/QaReactionBar"
import { type QaMessageBubbleAnswer } from "../types"

/** One bubble + author line, with no interactive controls — used for the top answer's OWN rendering and for every read-only reply beneath it. */
interface MessageRowInteractive {
    canAccept: boolean
    onAcceptAnswer: (accepted: boolean) => void
    onReact: (type: QaReactionType | null) => void
}
interface MessageRowProps {
    answer: QaMessageBubbleAnswer
    currentUserId: string | null
    interactive: MessageRowInteractive | null
}
export const MessageRow = ({
    answer,
    currentUserId,
    interactive,
}: MessageRowProps) => {
    const isMine = currentUserId != null && currentUserId === answer.author.id
    const displayName = isMine ? "You" : answer.author.displayName

    const authorRow = (
        <StackH
            gap={2}
            principles={["icon-text", "separator-dot"]}
            align="center"

            items={[
                () => <Avatar src={answer.author.avatarUrl} name={answer.author.displayName} seed={answer.author.id} size="sm" />,
                () => <Typography size="xs" weight="medium" text={displayName} />,
                () => <Typography size="xs" color="muted" text={answer.createdTimeAgo} />,
                ...(answer.isAcceptedAnswer ? [() => <Chip tone="success" text="Accepted answer" />] : []),
            ]}
        />
    )

    const reactionRow = interactive ? (
        <StackH
            gap={3}
            principles={["flex-action"]}
            align="center"

            items={[
                () => (
                    <QaReactionBar
                        count={answer.reactionCount}
                        myReaction={answer.myReaction}
                        onReact={interactive.onReact}

                    />
                ),
                ...(interactive.canAccept ? [() => (
                    <Button
                        variant={answer.isAcceptedAnswer ? "secondary" : "ghost"}
                        size="sm"
                        prefixIcon={CheckCircleIcon}
                        label={answer.isAcceptedAnswer ? "Unaccept" : "Mark as the correct answer"}
                        onPress={() => interactive.onAcceptAnswer(!answer.isAcceptedAnswer)}

                    />
                )] : []),
            ]}
        />
    ) : null

    const bubbleBody = (
        <>
            {authorRow}

            <QaChatBubble role={isMine ? "user" : "assistant"}>
                <div className="[&_p]:m-0">
                    <MarkdownContent source={answer.body} measure="compact" />
                </div>
            </QaChatBubble>

            {reactionRow}
        </>
    )

    return (
        <div className={cn("flex w-full", isMine ? "justify-end" : "justify-start")}>
            <div className="max-w-[92%]">
                <StackV gap={2} principles={["title-subtitle"]} align={isMine ? "end" : undefined} classNames={["min-w-0"]} items={[() => bubbleBody]} />
            </div>
        </div>
    )
}

import React, { useState } from "react"
import { type SkeletonProps } from "@sb-components/frames/_slot"
import { Button as HeroButton, Popover as HeroPopover } from "@heroui/react"
import { Typography } from "@sb-components/atoms/text/Typography/Typography"
import { ReactionPicker } from "@sb-components/atoms/feedback/ReactionPicker/ReactionPicker"
import { StackH } from "@sb-components/frames/Stack/Stack"
import { ReactionGlyph } from "./ReactionGlyph"
import { REACTION_BY_TYPE, type ReactionButtonProps, type ReactionType } from "./types"

export type { ReactionType, ReactionCount, ReactionButtonProps } from "./types"

/**
 * BLOCK — `ReactionButton`: the Facebook-style six-emotion reaction control —
 * pill trigger + Popover picker + compact summary. Shared verbatim between
 * `ContentReaction` (the lesson-level reaction) and each comment row in
 * `ContentDiscussion`'s thread — the SAME control real `src`'s `ReactionBar`
 * is, reused between `InteractionBar` and `CommentItem`.
 *
 *  LEAF by STRUCTURE (§14d.2). Which emotion is picked and whether the
 * summary is empty keep the same two-part shape ⇒ states. The caller
 * flipping `isSkeleton` is its own leaf.
 */

/**
 * The reaction trigger + picker + summary. See the file header for the full contract.
 *
 * @param props - {@link ReactionButtonProps}
 */
const ReactionButton = ({
    myReaction = null,
    counts = [],
    onReact,
    isPending = false,
    isSkeleton = false,
}: ReactionButtonProps) => {
    // controlled so the popover closes as soon as an emotion is picked — mirrors real ReactionBar
    const [isOpen, setIsOpen] = useState(false)

    const total = counts.reduce((sum, entry) => sum + entry.count, 0)
    // busiest emotions first, top 3 — same cap real ReactionBar uses for the stacked summary
    const topReactions = counts
        .slice()
        .sort((prev, next) => next.count - prev.count)
        .slice(0, 3)
        .map((entry) => REACTION_BY_TYPE[entry.type])

    const handlePick = (type: ReactionType) => {
        setIsOpen(false)
        onReact(myReaction === type ? null : type)
    }

    if (isSkeleton) {
        return <span className="inline-block h-8 w-28 animate-pulse rounded-full bg-default" />
    }

    // compact summary: stacked top emojis + total — dropped entirely at zero
    const summaryRow = total > 0 ? (
        <StackH
            gap={3}
            principles={["value-row"]}
            align="center"
            isSkeleton={isSkeleton}
            items={[
                () => (
                    <span className="flex items-center -space-x-1">
                        {topReactions.map((reaction) => (
                            <ReactionGlyph key={reaction.type} type={reaction.type} size="sm" />
                        ))}
                    </span>
                ),
                ({ isSkeleton }: SkeletonProps) => <Typography isSkeleton={isSkeleton} size="sm" text={String(total)} />,
            ]}
        />
    ) : null

    const triggerAndSummary = (
        <>
            {/* trigger: opens the 6-emotion picker; shows the viewer's own pick once set */}
            <HeroPopover isOpen={isOpen} onOpenChange={setIsOpen}>
                <HeroPopover.Trigger>
                    <HeroButton
                        variant="tertiary"
                        isDisabled={isPending}
                        className="rounded-full"

                    >
                        <ReactionGlyph type={myReaction ?? "like"} size="sm" />
                        <span className="text-sm">
                            {myReaction ? REACTION_BY_TYPE[myReaction].label : "React"}
                        </span>
                    </HeroButton>
                </HeroPopover.Trigger>
                {/* TODO(atom): bold skin-shape (rounded-full + px-2 py-1 pill) — a frame cannot own it,
                    Wrap with a hand-set data-principles for now. `className` sits on `HeroPopover.Content`
                    itself (the vendor's OWN rendered surface, react-aria `Popover`), not a raw <div>
                    we author, so `Box` can't wrap it (moving the shape down onto an inner wrapping
                    Box would leave the real popover surface with its default non-pill radius showing
                    behind it — a visible shape regression). `data-principles` on `Content` directly is
                    type-safe (forwarded through `DOMAttributes`), so tagged in place instead. Needs a
                    dedicated pill-popover atom/composite to own this shape. Same declared shape
                    as `QaReactionBar.tsx`'s trigger.
                    inset-exception: pill geometry, the same px-2 py-1 HeroUI ships in chip.css. */}
                <HeroPopover.Content data-principles="pill-pad" className="overflow-visible rounded-full px-2 py-1">
                    <ReactionPicker
                        items={Object.values(REACTION_BY_TYPE).map((reaction) => ({ key: reaction.type, imgSrc: `/reactions/${reaction.type}.svg`, label: reaction.label }))}
                        activeKey={myReaction}
                        onSelect={(key) => handlePick(key as ReactionType)}
                    />
                </HeroPopover.Content>
            </HeroPopover>

            {summaryRow}
        </>
    )

    return (
        <StackH gap={3} principles={["flex-action"]} align="center" isSkeleton={isSkeleton} items={[() => triggerAndSummary]} />
    )
}

export { ReactionButton }

import React from "react"
import type { ReactNode } from "react"
import { ResizableRail } from "@sb-components/behaviors/ResizableRail/ResizableRail"
import { Spinner } from "@sb-components/atoms/display/Spinner/Spinner"
import { StackH, StackV } from "@sb-components/frames/Stack/Stack"
import { EnrollGate, type EnrollGateProps } from "@sb-components/starci/blocks/learn/EnrollGate/EnrollGate"
import { ContentAiFab } from "@sb-components/starci/blocks/learn/ContentAiFab/ContentAiFab"
import {
    ContentAiSelectionAsk,
    type ContentAiSelectionAskAnchor,
} from "@sb-components/starci/blocks/learn/ContentAiSelectionAsk/ContentAiSelectionAsk"

/**
 * `LearnShell` — the wrapper mounted once per `/learn/**` scope. Five
 * structural leaves, each gaining or losing a whole node:
 *   - `RailSurface`        — rail mounted beside `children`, one floating FAB.
 *   - `NoRailSurface`      — no rail; `children` fills the width.
 *   - `SelectionAskActive` — gains the `ContentAiSelectionAsk` pill alongside
 *     the FAB.
 *   - `AiSuppressed`       — `isAssessmentLive` loses both AI trigger nodes.
 *   - `EnrollGated`        — the whole rail+children row is replaced by
 *     `EnrollGate`.
 */

/** Which `/learn/**` surface is currently active — drives whether a rail mounts. */
export type LearnSurface = "content" | "personalProject" | "leaderboard" | "other"

/** Surfaces whose real rail body (out of scope here, see file header) exists in the real app. */
const RAIL_SURFACES: ReadonlySet<LearnSurface> = new Set(["content", "leaderboard"])

/** Rail persistence + bounds — mirrors the real `learn/layout.tsx` rail's own defaults. */
const RAIL_STORAGE_KEY = "learn-shell-rail-width"
const RAIL_DEFAULT_WIDTH = 320
const RAIL_MIN_WIDTH = 256
const RAIL_MAX_WIDTH = 480
const RAIL_ARIA_LABEL = "Drag to resize the side panel"
const RAIL_LOADING_LABEL = "Loading side panel"

/**
 * Fields `LearnShell` relays into `EnrollGate` — see the file header's
 * "`preview` IS A RELAYED SLOT" note for why `preview`/`price` ride along with
 * `title`/`description`, plus the `onEnroll` callback the gate needs to fire.
 */
export interface LearnShellEnrollGateProps
    extends Pick<EnrollGateProps, "title" | "description" | "preview" | "price"> {
    /** Fired when the learner takes the gate's enroll CTA. */
    onEnroll: () => void
}

/**
 * A resolved, already-positioned "ask AI about this selection" request — see
 * the file header for why `LearnShell` never tracks the selection itself.
 */
export interface LearnShellSelectionAsk {
    /** Viewport point to plant the pill at (already resolved by the caller). */
    anchor: ContentAiSelectionAskAnchor
    /** `true` → the pill carries the "New" badge. */
    isNew?: boolean
}

/** Props for {@link LearnShell}. */
export interface LearnShellProps {
    /** Which `/learn/**` surface is mounted right now — drives which rail body would mount. */
    activeSurface: LearnSurface
    /** `true` → the active surface requires enrollment the viewer does not have; replaces the whole body with `EnrollGate`. */
    isEnrollGated: boolean
    /** `true` → a timed/live assessment is running; suppresses BOTH AI triggers regardless of `isEnrollGated`. */
    isAssessmentLive: boolean
    /** `title`/`description`/`preview`/`price` relayed into `EnrollGate`, plus its `onEnroll`. Required only while `isEnrollGated`. */
    enrollGateProps?: LearnShellEnrollGateProps
    /** Fired when the floating AI trigger is pressed — the real layout opens the AI chat rail/drawer in response. */
    onOpenAiChat: () => void
    /** `true` → that chat surface is already open, so `ContentAiFab` hides instead of floating on top of it. */
    isAiChatOpen?: boolean
    /** The current text-selection ask request, already resolved+positioned by the caller. `null`/omitted → no selection to react to. */
    selectionAsk?: LearnShellSelectionAsk | null
    /** Fired when the selection-ask pill is pressed. */
    onOpenSelectionAsk: () => void
    /** The active route's own content — the one place `ReactNode` is valid above frame tier (§12). */
    children: ReactNode
}

/**
 * The `/learn/**` layout shell. See the file header for the full contract, the
 * scope gaps left deliberately open, and why `LeaderboardCategoryNav` was not
 * reused despite the inventory hint.
 *
 * @param props - {@link LearnShellProps}
 */
const LearnShell = ({
    activeSurface,
    isEnrollGated,
    isAssessmentLive,
    enrollGateProps,
    onOpenAiChat,
    isAiChatOpen = false,
    selectionAsk = null,
    onOpenSelectionAsk,
    children,
}: LearnShellProps) => {
    // A locked surface has nothing real to ask AI about yet, on top of the
    // brief's own `isAssessmentLive` suppression.
    const showAiTriggers = !isEnrollGated && !isAssessmentLive

    const railAndContent = [
        ...(RAIL_SURFACES.has(activeSurface) ? [() => (
            <ResizableRail
                storageKey={RAIL_STORAGE_KEY}
                defaultWidth={RAIL_DEFAULT_WIDTH}
                minWidth={RAIL_MIN_WIDTH}
                maxWidth={RAIL_MAX_WIDTH}
                ariaLabel={RAIL_ARIA_LABEL}
                handleSide="right"
                className="h-full shrink-0 border-r border-default"

            >
                <StackV
                    gap={1}
                    principles={["sibling-stack"]}
                    align="center"
                    justify="center"
                    classNames={["h-full"]}

                    items={[() => <Spinner label={RAIL_LOADING_LABEL} />]}
                />
            </ResizableRail>
        )] : []),
        () => (
            <div className="min-w-0 flex-1">
                {children}
            </div>
        ),
    ]

    return (
        <div>
            {isEnrollGated && enrollGateProps != null ? (
                <EnrollGate
                    title={enrollGateProps.title}
                    description={enrollGateProps.description}
                    preview={enrollGateProps.preview}
                    price={enrollGateProps.price}
                    onEnroll={enrollGateProps.onEnroll}


                />
            ) : (
                <div className="min-h-[calc(100dvh-4rem)]">
                    <StackH
                        gap={1}
                        items={railAndContent}
                    />
                </div>
            )}

            {showAiTriggers ? (
                <>
                    <ContentAiFab
                        onOpen={onOpenAiChat}
                        isOpen={isAiChatOpen}


                    />
                    {selectionAsk != null ? (
                        <ContentAiSelectionAsk
                            onOpen={onOpenSelectionAsk}
                            anchor={selectionAsk.anchor}
                            isNew={selectionAsk.isNew}


                        />
                    ) : null}
                </>
            ) : null}
        </div>
    )
}

export { LearnShell }

import React, { useState } from "react"
import { CourseQaHeader, type CourseQaHeaderCrumb } from "@sb-components/starci/blocks/learn/CourseQaHeader/CourseQaHeader"
import { CourseQaInvite } from "@sb-components/starci/blocks/learn/CourseQaInvite/CourseQaInvite"
import { CourseQaEngagementStrip } from "@sb-components/starci/blocks/learn/CourseQaEngagementStrip/CourseQaEngagementStrip"
import { CourseQaComposer, type CourseQaComposerUser } from "@sb-components/starci/blocks/learn/CourseQaComposer/CourseQaComposer"
import { CourseQaToolbar, type CourseQaFilter } from "@sb-components/starci/blocks/learn/CourseQaToolbar/CourseQaToolbar"
import { CourseQaQuestionList, type CourseQaQuestionItem, type CourseQaCurrentUser } from "@sb-components/starci/blocks/learn/CourseQaQuestionList/CourseQaQuestionList"
import { Container } from "@sb-components/frames/Container/Container"
import { StackV } from "@sb-components/frames/Stack/Stack"

/**
 * `CourseQaPage` — the screen for the course-wide Q&A roll-up. A screen owns a
 * list of functions: it calls blocks, places them in frames, and hands each
 * typed data. Six functions, in reading order: what this board is · the
 * "you're not learning alone" readout · ask a new question · filter/search the
 * board · the questions themselves, paged. The screen owns one branch,
 * `isInvitationEmpty`: only `all`/`engagement` with no search proves a true
 * zero (the `Invitation` leaf); every other empty result is
 * `CourseQaQuestionList`'s own `Empty` leaf one layer down.
 */

/** The signed-in viewer, in this screen's own vocabulary. Adapted into each composed block's own shape below. */
export interface CourseQaViewer {
    /** Display name — seeds both the composer avatar and (future) the question list's "own question" swap. */
    displayName: string
    /** Avatar image URL. Omitted → each composed atom falls back per its own chain. */
    avatarUrl?: string
}

/** Fixed board-wide copy for the "nobody has ever asked anything" invitation — see file header. */
const INVITE_TITLE = "No questions yet"
const INVITE_HINT = "Browse the course content, then come back to ask the first question."
const INVITE_CTA = "Browse course content"

/** Fixed accessible names — board-wide, never course-specific (see file header). */
const FILTER_ARIA_LABEL = "Question filter"
const PAGER_ARIA_LABEL = "Question list navigation"

/** Props for {@link CourseQaPage}. */
export interface CourseQaPageProps {
    /** Breadcrumb trail as data. */
    breadcrumbItems?: Array<CourseQaHeaderCrumb>
    /** Page title, e.g. "Q&A". */
    title: string
    /** One-sentence description of what this Q&A board is for. */
    description?: string
    /** Learners enrolled in the course. Omitted → the engagement strip drops that line entirely (real numbers only). */
    enrollmentCount?: number
    /** Total questions on the board — feeds the engagement strip and (see file header) the toolbar's result count. */
    totalQuestions: number
    /** Of {@link CourseQaPageProps.totalQuestions}, how many have at least one answer. */
    answeredQuestions: number

    /** Which status/scope filter is active. */
    filter: CourseQaFilter
    /** Fired with the filter the reader picked. */
    onFilterChange: (filter: CourseQaFilter) => void
    /** Current text in the search field. */
    searchValue: string
    /** Fired with the new query on every keystroke. */
    onSearchChange: (value: string) => void

    /** The signed-in viewer. `null` → composer draws no avatar and the list's "own question" swap never fires. */
    currentUser: CourseQaViewer | null
    /** Signed-in viewer's id — drives the "own question" swap one layer down. `null` when signed out. */
    currentUserId: string | null

    /** The current page's questions, in display order. */
    questions: ReadonlyArray<CourseQaQuestionItem>
    /** 1-based current page. */
    page: number
    /** Total page count. */
    totalPages: number
    /** Fired with the 1-based page the reader picked. */
    onPageChange: (page: number) => void

    /** Fired when the reader submits a new course-general question, with the finished body text. */
    onAskQuestion: (body: string) => void
    /** Fired after an answer is posted/edited/deleted anywhere in the list. */
    onAnswered?: () => void
    /** Fired from the invitation's one way forward — back into the course content. */
    onGoToContent: () => void

    /**
     * `true` → every block that can mirror itself does, and the invitation
     * branch is skipped in favour of the populated shape (see file header).
     */
    isSkeleton?: boolean
}

/**
 * The course Q&A roll-up screen. See the file header for the function list,
 * the ported `isInvitationEmpty` branch, and the judgement calls on the
 * shared result count / list async lifecycle / viewer shape / composer draft.
 *
 * @param props - {@link CourseQaPageProps}
 */
const CourseQaPage = ({
    breadcrumbItems,
    title,
    description,
    enrollmentCount,
    totalQuestions,
    answeredQuestions,
    filter,
    onFilterChange,
    searchValue,
    onSearchChange,
    currentUser,
    currentUserId,
    questions,
    page,
    totalPages,
    onPageChange,
    onAskQuestion,
    onAnswered,
    onGoToContent,
    isSkeleton = false,
}: CourseQaPageProps) => {
    // Screen-local UI state for the composer's in-progress keystrokes — see
    // file header for why this is not a prop pair on this screen's contract.
    const [draft, setDraft] = useState("")

    // Ported verbatim from `src`'s `CourseQa/index.tsx` — see file header.
    const hasQuery = (filter !== "all" && filter !== "engagement") || searchValue.trim().length > 0
    const isInvitationEmpty = !isSkeleton && questions.length === 0 && !hasQuery

    const composerUser: CourseQaComposerUser | undefined = currentUser
        ? { name: currentUser.displayName, avatarSrc: currentUser.avatarUrl }
        : undefined
    const listCurrentUser: CourseQaCurrentUser | null = currentUser
        ? { username: currentUser.displayName, avatar: currentUser.avatarUrl }
        : null

    const handleAskQuestion = () => {
        onAskQuestion(draft)
        setDraft("")
    }

    const questionSection = (
        <>
            <CourseQaEngagementStrip

                enrollmentCount={enrollmentCount}
                totalQuestions={totalQuestions}
                answeredQuestions={answeredQuestions}
                isSkeleton={isSkeleton}

            />
            <CourseQaComposer

                mode="collapsible"
                currentUser={composerUser}
                value={draft}
                onValueChange={setDraft}
                placeholder="Ask a question about this course…"
                onSubmit={handleAskQuestion}
                isSkeleton={isSkeleton}

            />
            <CourseQaToolbar

                filter={filter}
                onFilterChange={onFilterChange}
                searchValue={searchValue}
                onSearchChange={onSearchChange}
                resultCount={totalQuestions}
                filterAriaLabel={FILTER_ARIA_LABEL}
                isSkeleton={isSkeleton}

            />
            <CourseQaQuestionList

                questions={questions}
                isLoading={isSkeleton}
                page={page}
                totalPages={totalPages}
                onPageChange={onPageChange}
                currentUserId={currentUserId}
                currentUser={listCurrentUser}
                onAnswered={onAnswered}
                pagerAriaLabel={PAGER_ARIA_LABEL}
                isSkeleton={isSkeleton}

            />
        </>
    )

    const courseQaSections = (
        <>
            <CourseQaHeader

                breadcrumbItems={breadcrumbItems}
                title={title}
                description={description}
                isSkeleton={isSkeleton}

            />
            {isInvitationEmpty ? (
                <CourseQaInvite

                    title={INVITE_TITLE}
                    hint={INVITE_HINT}
                    ctaLabel={INVITE_CTA}
                    onGoToContent={onGoToContent}
                    isSkeleton={isSkeleton}

                />
            ) : (
                <StackV gap={6} isSkeleton={isSkeleton} items={[() => questionSection]} />
            )}
        </>
    )

    const courseQaBody = <StackV gap={6} isSkeleton={isSkeleton} items={[() => courseQaSections]} />

    return <Container size="md" padding={6} body={() => courseQaBody} />
}

export { CourseQaPage }

import React from "react"
import { MapTrifoldIcon, ShareNetworkIcon } from "@phosphor-icons/react"
import { MindMapRail, type MindMapRailItem, type MindMapRailTier } from "@sb-components/starci/blocks/learn/MindMapRail/MindMapRail"
import { MindMapContinueButton } from "@sb-components/starci/blocks/learn/MindMapContinueButton/MindMapContinueButton"
import { MindMapFullscreenButton, type MindMapFullscreenButtonAriaLabels } from "@sb-components/starci/blocks/learn/MindMapFullscreenButton/MindMapFullscreenButton"
import { Legend, type LegendItem } from "@sb-components/composites/stats/Legend/Legend"
import { AsyncContentEmpty } from "@sb-components/composites/async/AsyncContent/AsyncContent"
import { ResizableRail } from "@sb-components/behaviors/ResizableRail/ResizableRail"
import { StackH, StackV } from "@sb-components/frames/Stack/Stack"

/**
 * SCREEN — `MindMapPage`: the course keyword graph, in its two real shapes.
 * See the component's own file header for the full function list, the two
 * corrections against the planner's proposed tree (`MindMapBackButton` and
 * `FloatingActionButton` are both absent, on purpose), and why the canvas
 * region is a documented §B3 gap rather than a faked ReactFlow mount.
 *
 * FIVE LEAVES, by STRUCTURE — `workspace` and `standalone` are different
 * compositions (not one shape with a variant flag flipping paint), so each
 * gets its own leaves; `Empty` and `Loading` each lose or swap real nodes
 * (rail's shimmer vs. its populated list; the three floating blocks present
 * vs. absent), which is a structural change, not a data condition of one leaf.
 */

/** Which shape of the mind map this screen renders — see the file header. */
export type MindMapVariant = "workspace" | "standalone"

/** Props for {@link MindMapPage}. */
export interface MindMapPageProps {
    /** Which shape to render — see the file header for how the two differ. */
    variant: MindMapVariant

    // ── `workspace`: the `MindMapRail` search pane ──
    /** Current search text (controlled). Ignored outside `workspace`. */
    query: string
    /** Fired on every keystroke in the rail's search field. */
    onQuery: (query: string) => void
    /** Current popularity-tier filter. */
    tier: MindMapRailTier
    /** Fired with the tier the reader picked in the rail's funnel popover. */
    onTier: (tier: MindMapRailTier) => void
    /** The current query+tier's matching keywords, in display order. */
    items: Array<MindMapRailItem>
    /** Which result is currently focused on the canvas, if any. */
    selectedId?: string
    /** Fired with a result's id when its rail row is pressed. */
    onPick: (id: string) => void
    /** `true` → the rail's own query/tier fetch is in flight (independent of `isSkeleton`). */
    isRailLoading?: boolean
    /** Accessible name for the rail's search field. */
    railAriaLabel: string
    /** Accessible name for the rail's tier filter group. */
    railTierAriaLabel: string
    /** Accessible name for the rail's drag-to-resize handle. */
    railResizeAriaLabel: string

    // ── `standalone`: floating chrome over the canvas ──
    /** Href of the viewer's next unread lesson/challenge, or `null` when none resolves. Ignored outside `standalone`. */
    resumeHref?: string | null
    /** `true` → the viewer has read everything the map has to offer. */
    allContentDone?: boolean
    /** Fired on a resume press. */
    onResume?: () => void
    /** Accessible name for the resume action. */
    continueAriaLabel?: string
    /** Legend entries — colour swatch + label, e.g. done/in-progress/not-started/locked/current. */
    legendItems?: Array<LegendItem>
    /** Fired on every press of the zoom-in button. */
    onZoomIn?: () => void
    /** Fired on every press of the zoom-out button. */
    onZoomOut?: () => void
    /** Fired on every press of the fullscreen toggle. */
    onToggleFullscreen?: () => void
    /** `true` → canvas is currently fullscreen. */
    isFullscreen?: boolean
    /** Per-button accessible names for the zoom/fullscreen rail. */
    fullscreenAriaLabels?: MindMapFullscreenButtonAriaLabels

    // ── shared ──
    /** `true` → every block that can mirror itself does; the canvas gap swaps to its loading wording. */
    isSkeleton?: boolean
    /** `true` → the course has no authored map/modules yet. `workspace`-ONLY — see the file header. */
    isEmpty?: boolean
}

/** localStorage key + bounds the real `MindMapWorkspace` persists the rail width under. */
const RAIL_STORAGE_KEY = "mindmap-rail-width"
const RAIL_DEFAULT_WIDTH = 320
const RAIL_MIN_WIDTH = 264
const RAIL_MAX_WIDTH = 520

const CANVAS_GAP_TITLE = "Concept map region"
const CANVAS_GAP_DESCRIPTION = "The real ReactFlow graph (nodes, drawer, minimap) isn't built this pass — this block is where it will mount (§B3)."
const CANVAS_GAP_LOADING_TITLE = "Loading map…"

const WORKSPACE_EMPTY_TITLE = "This course has no concept map yet"
const WORKSPACE_EMPTY_DESCRIPTION = "The map is generated automatically once the course has enough modules — check back later."

/** Props for the {@link MindMapCanvasGap} stand-in below. */
interface MindMapCanvasGapProps {
    isLoading?: boolean
}

/**
 * Stand-in for the out-of-reach ReactFlow engine (§B3) — see the file header's
 * "CANVAS GAP" note for why `AsyncContentEmpty` is the reused shape here.
 */
const MindMapCanvasGap = ({ isLoading = false}: MindMapCanvasGapProps) => (
    <StackV
        gap={1}
        principles={["sibling-stack"]}
        align="center"
        justify="center"
        classNames={["h-full"]}

        items={[() => (
            <AsyncContentEmpty

                icon={ShareNetworkIcon}
                title={isLoading ? CANVAS_GAP_LOADING_TITLE : CANVAS_GAP_TITLE}
                description={isLoading ? undefined : CANVAS_GAP_DESCRIPTION}
            />
        )]}
    />
)

/**
 * `workspace` empty state — the course has no authored map yet. Replaces the
 * ENTIRE spine, same "one frame + one composite, each badging itself" shape
 * `CourseContents`/`ModulePage` already established for this exact case.
 */
const MindMapWorkspaceEmpty = () => (
    <div className="h-[calc(100dvh-4rem)]">
        <StackV
            gap={1}
            principles={["sibling-stack"]}
            align="center"
            justify="center"
            items={[() => (
                <AsyncContentEmpty

                    icon={MapTrifoldIcon}
                    title={WORKSPACE_EMPTY_TITLE}
                    description={WORKSPACE_EMPTY_DESCRIPTION}
                />
            )]}
        />
    </div>
)

/**
 * The mind-map screen, in its two shapes. See the file header for the function
 * list, the two corrections against the planner's proposed tree, and the
 * canvas gap.
 *
 * @param props - {@link MindMapPageProps}
 */
const MindMapPage = ({
    variant,
    query,
    onQuery,
    tier,
    onTier,
    items,
    selectedId,
    onPick,
    isRailLoading = false,
    railAriaLabel,
    railTierAriaLabel,
    railResizeAriaLabel,
    resumeHref = null,
    allContentDone = false,
    onResume,
    continueAriaLabel = "",
    legendItems = [],
    onZoomIn = () => {},
    onZoomOut = () => {},
    onToggleFullscreen = () => {},
    isFullscreen = false,
    fullscreenAriaLabels = { zoomIn: "", zoomOut: "", toggleFullscreen: "" },
    isSkeleton = false,
    isEmpty = false,
}: MindMapPageProps) => {
    if (variant === "workspace" && isEmpty) {
        return <MindMapWorkspaceEmpty />
    }

    const railSection = (
        <MindMapRail

            query={query}
            onQuery={onQuery}
            tier={tier}
            onTier={onTier}
            items={items}
            selectedId={selectedId}
            onPick={onPick}
            isLoading={isRailLoading}
            ariaLabel={railAriaLabel}
            tierAriaLabel={railTierAriaLabel}
            isSkeleton={isSkeleton}

        />
    )

    // The canvas region's floating chrome — in the real app these render as the
    // SAME ReactFlow engine's own Panel children, see the file header's
    // "OVERLAYS ARE FRAMES" note.
    const canvasOverlays = (
        <>
            <div className="absolute inset-x-0 top-4 z-10">
                <StackV
                    gap={1}
                    principles={["sibling-stack"]}
                    align="center"
                    isSkeleton={isSkeleton}
                    items={[() => (
                        <MindMapContinueButton

                            resumeHref={resumeHref}
                            allContentDone={allContentDone}
                            onResume={onResume}
                            continueAriaLabel={continueAriaLabel}
                            isSkeleton={isSkeleton}
                        />
                    )]}
                />
            </div>
            <div className="absolute bottom-4 left-4 z-10">
                <StackV
                    gap={1}
                    isSkeleton={isSkeleton}
                    items={[() => (
                        <div>
                            <Legend items={legendItems} />
                        </div>
                    )]}
                />
            </div>
            <div className="absolute bottom-4 right-4 z-10">
                <StackV
                    gap={1}
                    isSkeleton={isSkeleton}
                    items={[() => (
                        <MindMapFullscreenButton

                            onZoomIn={onZoomIn}
                            onZoomOut={onZoomOut}
                            onToggleFullscreen={onToggleFullscreen}
                            isFullscreen={isFullscreen}
                            ariaLabels={fullscreenAriaLabels}
                            isSkeleton={isSkeleton}
                        />
                    )]}
                />
            </div>
        </>
    )

    const canvasRegion = (
        <>
            <MindMapCanvasGap isLoading={isSkeleton} />
            {variant === "standalone" && !isSkeleton ? canvasOverlays : null}
        </>
    )

    const workspaceRail = (
        <ResizableRail
            storageKey={RAIL_STORAGE_KEY}
            defaultWidth={RAIL_DEFAULT_WIDTH}
            minWidth={RAIL_MIN_WIDTH}
            maxWidth={RAIL_MAX_WIDTH}
            ariaLabel={railResizeAriaLabel}
            handleSide="right"
            className="h-full shrink-0 border-r border-default"

        >
            <div className="overflow-y-auto">
                <StackV
                    padding={6}
                    principles={["page-pad"]}
                    gap={1}
                    classNames={["h-full"]}
                    isSkeleton={isSkeleton}
                    items={[() => railSection]}
                />
            </div>
        </ResizableRail>
    )

    const workspaceSections = (
        <>
            {variant === "workspace" ? workspaceRail : null}
            {/* The canvas region: the out-of-reach engine's gap, plus (standalone only) the
                floating chrome that in the real app renders as the SAME engine's own Panel
                children — see the file header's "OVERLAYS ARE FRAMES" note. */}
            <div className="relative">
                <StackV
                    gap={1}
                    classNames={["min-w-0", "flex-1"]}
                    isSkeleton={isSkeleton}
                    items={[() => canvasRegion]}
                />
            </div>
        </>
    )

    return (
        <div className="h-[calc(100dvh-4rem)]">
            <StackH gap={1} isSkeleton={isSkeleton} items={[() => workspaceSections]} />
        </div>
    )
}

export { MindMapPage }
